        [126] = 584,
    },
    heights = {},
    depths = {},
}
do
    local fm = font_metrics["Helvetica-Bold"]
    for i = 32, 126 do
        fm.heights[i] = font_metrics["Helvetica"].heights[i]
        fm.depths[i] = font_metrics["Helvetica"].depths[i]
    end
end


