sample_texts[81] = "The concept of infinity has fascinated mathematicians and philosophers for " ..
    "millennia, from the paradoxes of Zeno to Cantor's revolutionary transfinite " ..
    "arithmetic. Cantor demonstrated that different infinite sets can have different " ..
    "sizes, or cardinalities: the set of natural numbers is countably infinite, while " ..
    "the set of real numbers is uncountably infinite, meaning no one-to-one correspondence " ..
    "exists between them. This discovery led to profound questions about the foundations " ..
    "of mathematics, including the continuum hypothesis, which asks whether any infinite " ..
    "cardinal exists between these two. Godel and Cohen showed this question is " ..
    "independent of the standard axioms of set theory."

sample_texts[82] = "Volcanic eruptions represent one of the most dramatic manifestations of the " ..
    "Earth's internal energy. When magma, a mixture of molten rock, dissolved gases, " ..
    "and suspended crystals, reaches the surface, it can erupt explosively or effusively " ..
    "depending on its viscosity and gas content. Explosive eruptions, typical of " ..
    "subduction zone volcanoes, produce towering ash columns, pyroclastic flows, and " ..
    "lahars that can devastate surrounding regions. Effusive eruptions, characteristic " ..
    "of oceanic hotspot volcanoes like those in Hawaii, produce relatively gentle " ..
    "lava flows that build broad shield volcanoes over millions of years."

sample_texts[83] = "The double helix structure of DNA, discovered by Watson and Crick in 1953 with " ..
    "crucial contributions from Rosalind Franklin and Maurice Wilkins, revealed how " ..
    "genetic information is encoded and replicated. The molecule consists of two " ..
    "antiparallel polynucleotide strands wound around each other, with complementary " ..
    "base pairs adenine-thymine and guanine-cytosine holding the strands together " ..
    "through hydrogen bonds. This complementary base-pairing provides the mechanism " ..
    "for faithful replication of genetic information during cell division, as each " ..
    "strand serves as a template for the synthesis of its complement."

sample_texts[84] = "Abstract algebra studies algebraic structures such as groups, rings, and fields " ..
    "by focusing on their formal properties rather than the nature of their elements. " ..
    "A group consists of a set equipped with an associative binary operation, an " ..
    "identity element, and inverses for every element. Rings add a second operation, " ..
    "typically called multiplication, that distributes over the first. Fields require " ..
    "both operations to form commutative groups, excluding zero from the multiplicative " ..
    "group. These abstract structures appear throughout mathematics, capturing " ..
    "symmetry, number systems, and polynomial arithmetic in a unified framework."

sample_texts[85] = "The circulatory system transports oxygen, nutrients, hormones, and immune cells " ..
    "throughout the body while simultaneously removing carbon dioxide and metabolic " ..
    "waste products. The heart, a muscular pump with four chambers, drives blood " ..
    "through two separate circuits: the pulmonary circuit to the lungs for gas " ..
    "exchange, and the systemic circuit to all other tissues. Arteries carry blood " ..
    "away from the heart under high pressure, branching into progressively smaller " ..
    "arterioles and eventually into capillaries where exchange with tissues occurs. " ..
    "Veins return blood to the heart at lower pressure, assisted by skeletal muscle " ..
    "contractions and one-way valves."

sample_texts[86] = "Game theory provides a mathematical framework for analyzing strategic interactions " ..
    "between rational decision-makers. In a strategic game, each player chooses an " ..
    "action from their available strategies, and the outcome depends on the combination " ..
    "of all players' choices. Nash equilibrium, the central solution concept, describes " ..
    "a profile of strategies from which no player can unilaterally improve their payoff " ..
    "by switching to a different strategy. Applications span economics, political " ..
    "science, evolutionary biology, and computer science, from auction design to " ..
    "understanding animal behavior."

sample_texts[87] = "The Romantic movement in literature and the arts, emerging in the late eighteenth " ..
    "century as a reaction against Enlightenment rationalism, emphasized emotion, " ..
    "imagination, individualism, and reverence for nature. Romantic poets including " ..
    "Wordsworth, Coleridge, Byron, Shelley, and Keats sought to capture the sublime " ..
    "in nature and the depths of human feeling through innovative poetic forms and " ..
    "vivid imagery. The movement's influence extended beyond literature to painting, " ..
    "music, philosophy, and politics, shaping cultural attitudes toward creativity, " ..
    "genius, and the relationship between humanity and the natural world."

sample_texts[88] = "Semiconductor physics describes the behavior of materials with electrical " ..
    "conductivity between that of metals and insulators. The band theory of solids " ..
    "explains semiconductor behavior through the energy gap between the valence band, " ..
    "where electrons are bound to atoms, and the conduction band, where electrons " ..
    "move freely through the crystal. Doping, the deliberate introduction of impurity " ..
    "atoms, creates either n-type semiconductors with excess electrons or p-type " ..
    "semiconductors with excess holes. The p-n junction formed at the interface " ..
    "between these types is the fundamental building block of all semiconductor " ..
    "electronic devices."

sample_texts[89] = "Paleontology reconstructs the history of life on Earth through the study of " ..
    "fossils, the preserved remains or traces of organisms that lived in the " ..
    "geological past. The fossil record, though incomplete, documents major " ..
    "evolutionary transitions including the origin of multicellular life, the " ..
    "colonization of land, the rise and fall of the dinosaurs, and the diversification " ..
    "of mammals following the end-Cretaceous mass extinction. Radiometric dating " ..
    "methods provide absolute age determinations, while biostratigraphy uses the " ..
    "distribution of fossils to establish relative temporal relationships between " ..
    "sedimentary rock layers across different geographic locations."

sample_texts[90] = "Signal processing encompasses the theory and practice of analyzing, modifying, " ..
    "and synthesizing signals, which are representations of time-varying or spatially " ..
    "varying physical quantities. The Fourier transform, which decomposes a signal " ..
    "into its constituent frequencies, provides the fundamental analytical tool. " ..
    "Digital signal processing implements these operations on discrete samples using " ..
    "algorithms executed by digital hardware. Applications include audio compression, " ..
    "image enhancement, radar systems, communications, medical imaging, seismology, " ..
    "and speech recognition, making signal processing one of the most broadly " ..
    "applicable branches of engineering."

sample_texts[91] = "The philosophy of science examines the foundations, methods, and implications of " ..
    "scientific knowledge. Karl Popper argued that the demarcation criterion separating " ..
    "science from non-science is falsifiability: a theory is scientific if and only if " ..
    "it makes predictions that could in principle be shown to be false. Thomas Kuhn " ..
    "challenged this view with his concept of paradigm shifts, arguing that science " ..
    "proceeds through periods of normal science punctuated by revolutionary changes " ..
    "in the conceptual framework. These philosophical debates continue to inform " ..
    "discussions about scientific methodology, realism, and the nature of progress."

sample_texts[92] = "Photovoltaic cells convert sunlight directly into electrical energy through the " ..
    "photovoltaic effect, first observed by Alexandre Edmond Becquerel in 1839. " ..
    "Modern silicon solar cells consist of a p-n junction that generates a voltage " ..
    "when photons with sufficient energy excite electrons from the valence band to " ..
    "the conduction band. The theoretical maximum efficiency of a single-junction " ..
    "silicon cell is approximately thirty-three percent, limited by thermalization " ..
    "losses and the mismatch between the solar spectrum and the semiconductor band " ..
    "gap. Multi-junction cells, concentrating optics, and novel materials such as " ..
    "perovskites promise further improvements in efficiency and cost reduction."

sample_texts[93] = "Fluid mechanics governs phenomena from the flight of aircraft to the circulation " ..
    "of blood through the body, from weather patterns spanning continents to the " ..
    "mixing of cream in coffee. The Navier-Stokes equations, which express conservation " ..
    "of momentum for a viscous fluid, represent one of the most important sets of " ..
    "equations in mathematical physics. Despite their fundamental importance, proving " ..
    "the existence and smoothness of solutions in three dimensions remains one of the " ..
    "unsolved Millennium Prize Problems, highlighting the profound mathematical " ..
    "challenges posed by fluid dynamics."

sample_texts[94] = "The art of calligraphy has been practiced for thousands of years across diverse " ..
    "cultural traditions. In East Asia, calligraphy achieved the status of a fine " ..
    "art form, with masters spending decades perfecting their brushwork. Arabic " ..
    "calligraphy developed elaborate decorative styles used in architectural " ..
    "ornamentation and manuscript illumination. Western calligraphy, rooted in " ..
    "Roman inscriptional capitals and medieval manuscript hands, continues to " ..
    "influence type design and graphic communication. All calligraphic traditions " ..
    "share a concern with the rhythmic quality of letterforms and the expressive " ..
    "potential of the writing instrument."

sample_texts[95] = "Ecological succession describes the process by which biological communities " ..
    "change over time following a disturbance. Primary succession begins on bare " ..
    "substrates such as newly formed volcanic rock or retreating glacier surfaces, " ..
    "while secondary succession occurs where vegetation has been removed but soil " ..
    "remains intact. Pioneer species, typically hardy organisms with rapid dispersal " ..
    "and growth rates, colonize disturbed areas first, gradually modifying conditions " ..
    "to favor the establishment of later successional species. The climax community, " ..
    "reached after decades or centuries depending on the ecosystem, represents a " ..
    "relatively stable state of dynamic equilibrium."

sample_texts[96] = "Number theory, often called the queen of mathematics, studies the properties " ..
    "and relationships of integers. Prime numbers, the fundamental building blocks " ..
    "of multiplication, exhibit a distribution that is simultaneously regular in the " ..
    "large and unpredictable in detail. The Prime Number Theorem, proved independently " ..
    "by Hadamard and de la Vallee Poussin in 1896, establishes that the number of " ..
    "primes less than n grows asymptotically as n divided by the natural logarithm " ..
    "of n. The Riemann Hypothesis, which concerns the zeros of the Riemann zeta " ..
    "function and implies the strongest known error bound in the Prime Number Theorem, " ..
    "remains unproven after more than one hundred sixty years."

sample_texts[97] = "Neuroplasticity refers to the brain's ability to reorganize itself by forming " ..
    "new neural connections throughout life. This capacity enables learning, memory " ..
    "formation, and recovery from brain injury. Synaptic plasticity, the strengthening " ..
    "or weakening of connections between neurons based on their activity patterns, " ..
    "provides the cellular mechanism for learning. Long-term potentiation, first " ..
    "described in the hippocampus, increases synaptic strength following repeated " ..
    "stimulation and is widely believed to underlie memory consolidation. Structural " ..
    "plasticity, involving the growth of new synapses and even new neurons in certain " ..
    "brain regions, operates on longer timescales."

sample_texts[98] = "The philosophy of language investigates the nature of meaning, reference, and " ..
    "linguistic communication. Central questions include how words and sentences " ..
    "come to represent aspects of the world, how speakers convey intentions beyond " ..
    "the literal meaning of their utterances, and the relationship between language " ..
    "and thought. Frege's distinction between sense and reference, Russell's theory " ..
    "of descriptions, Wittgenstein's language games, Austin's speech act theory, and " ..
    "Grice's theory of conversational implicature represent major contributions that " ..
    "continue to shape contemporary debate across philosophy, linguistics, and " ..
    "cognitive science."

sample_texts[99] = "Topography influences climate at every scale, from the global patterns produced " ..
    "by continental land masses and ocean basins to the microclimates created by " ..
    "individual hills and valleys. Mountain ranges force moist air masses to rise, " ..
    "cooling and condensing their moisture to produce orographic precipitation on " ..
    "the windward side and rain shadow deserts on the lee side. Proximity to large " ..
    "water bodies moderates temperature extremes through the high heat capacity of " ..
    "water. Urban areas create heat islands through the absorption of solar radiation " ..
    "by dark surfaces, waste heat from buildings and vehicles, and reduced evaporative " ..
    "cooling from the displacement of vegetation."

sample_texts[100] = "The molecular basis of heredity was established through a series of landmark " ..
    "experiments in the twentieth century. Griffith's transformation experiment in " ..
    "1928 showed that genetic information could be transferred between bacteria. " ..
    "Avery, MacLeod, and McCarty identified DNA as the transforming principle in " ..
    "1944. The Hershey-Chase experiment in 1952 confirmed that DNA, not protein, " ..
    "carries genetic information in bacteriophages. These discoveries, culminating " ..
    "in the elucidation of DNA structure in 1953, established the central dogma of " ..
    "molecular biology: information flows from DNA to RNA to protein, with DNA " ..
    "serving as the hereditary material of life."

